const resolveFeedbackNotificationActor = `-- name: ResolveFeedbackNotificationActor :one
SELECT CAST(candidate.user_id AS uuid) AS user_id
FROM UNNEST(CAST($1 AS uuid[])) WITH ORDINALITY candidate(user_id, priority)
INNER JOIN users account ON account.user_id = candidate.user_id AND account.is_active = true
WHERE candidate.user_id <> '00000000-0000-0000-0000-000000000000'
ORDER BY candidate.priority
LIMIT 1
`

type ResolveFeedbackNotificationActorParams struct {
	CandidateIds []uuid.UUID
}

func (q *Queries) ResolveFeedbackNotificationActor(ctx context.Context, arg ResolveFeedbackNotificationActorParams) (uuid.UUID, error) {
	row := q.db.QueryRow(ctx, resolveFeedbackNotificationActor, arg.CandidateIds)
	var user_id uuid.UUID
	err := row.Scan(&user_id)
	return user_id, err
}

